/**
 * #3649 slice A (cor:acl:140:09): the grant signature payload and the terms document, pinned byte for byte.
 *
 * The expected bytes come from `src/lib/grantSignature.fixture.json`, generated by
 * `scripts/generate-grant-signature-fixture.py` (Python hashlib, a hand-written RFC 8785 subset), never by the builder
 * under test. The three cor:acl:140:09 worked-example values are also pinned here as literals, so neither the fixture
 * nor the builder can drift from the spec without failing. Every refusal is a refusal, never a repair.
 */
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  GRANT_TERMS_V1, GrantTermsError, grantTermsBytes, grantTermsFromRow, grantTermsHash, type GrantTerms, type GrantTermsRow,
} from '../grants/terms.js';
import { GRANT_SIGNATURE_PAYLOAD_V1, CURRENT_GRANT_SIGNATURE_PAYLOAD_VERSION, grantSignaturePayloadBytes } from './grantPayload.js';
import { SIGNATURE_PAYLOAD_V3, signatureChallenge, signaturePayloadBytes, UnsupportedSignaturePayloadError } from './payload.js';

interface FixtureTerms {
  appId: string; holder: { kind: GrantTerms['holder']['kind']; id: string }; action: string;
  values: Record<string, string | string[]>; startsAt: string | null; expiresAt: string | null; maxUses: number | null; reason: string;
}
interface GrantCase {
  name: string; grantId: string; recordVersion: number; requestId: string; terms: FixtureTerms;
  termsUtf8: string; termsHash: string; payloadUtf8: string; canonical: string; challengeHex: string; challengeBase64url: string;
}
const fixture = JSON.parse(readFileSync(new URL('../grantSignature.fixture.json', import.meta.url), 'utf8')) as {
  version: string; termsVersion: string; challengeAlgorithm: string; cases: GrantCase[];
};
const byName = (name: string) => fixture.cases.find((c) => c.name === name)!;
const termsOf = (t: FixtureTerms): GrantTerms => ({
  ...t, startsAt: t.startsAt === null ? null : new Date(t.startsAt), expiresAt: t.expiresAt === null ? null : new Date(t.expiresAt),
});
const sha256hex = (s: string | Buffer) => createHash('sha256').update(s).digest('hex');
const SPEC = termsOf(byName('spec-example').terms);
const payloadOf = (c: GrantCase) => ({ grantId: c.grantId, recordVersion: c.recordVersion, termsHash: c.termsHash, requestId: c.requestId });

describe('G1: the fixture is the reference, and it matches cor:acl:140:09', () => {
  it('pins the complete case set and every byte of it', () => {
    expect(fixture).toMatchObject({ version: 'hadron-grant-signature-v1', termsVersion: 'hadron-grant-terms-v1', challengeAlgorithm: 'SHA-256' });
    expect(fixture.cases.map((c) => c.name)).toEqual([
      'spec-example', 'spec-reason-line-break', 'spec-version-2', 'other-request', 'holder-user', 'holder-worker',
      'holder-app', 'time-frame-and-count', 'no-time-frame', 'wildcard', 'list-stored-order', 'list-other-order',
      'keys-utf16-order', 'reason-escapes', 'reason-nfc', 'reason-nfd', 'reason-surrounding-space',
    ]);
    // Independent Python hashlib pin of the compact UTF-8 JSON: a regenerated fixture that moves any byte moves this hash.
    expect(sha256hex(JSON.stringify(fixture.cases))).toBe('b5ecc29640b1b53663fa4820b85693c03e38305bf7c72fcc76499118445a1e70');
  });

  it('carries the spec worked example literally: terms hash, both challenges, base64url', () => {
    expect(byName('spec-example').termsHash).toBe('0ef8421dcdd63e2052bee076b041298658d05b293056afc33deee231d92d1c4f');
    expect(byName('spec-example').challengeHex).toBe('bc53497fed2df2f4cf4dbf736abc91450d787fd271a7f7306050d82ece46934a');
    expect(byName('spec-example').challengeBase64url).toBe('vFNJf-0t8vTPTb9zaryRRQ14f9Jxp_cwYFDYLs5Gk0o');
    expect(byName('spec-reason-line-break').termsHash).toBe('1ba991bfe013723d5121135014808ba7356fc0eee41f3601d7572b6c38cd7501');
    expect(byName('spec-reason-line-break').challengeHex).toBe('44994ecb316c19063bb85ba177e45eae50704e329a4dd749eb9b7033a818aa0b');
    expect(byName('spec-version-2').challengeHex).toBe('eb59aead2b227570eaaca643518d8f005cf045cdff036725d5e7863a1ee2739a');
    expect(byName('spec-example').termsUtf8).toBe([
      'hadron-grant-terms-v1', 'app cm3k9x2a00001ab12cd34ef56', 'holder agent 01a05c157fe171208eef57f6ddb9b701',
      'action schedule.create', 'values {"entryNode":"01a10408afb6716c80d6944e8845467b"}', 'starts none',
      'expires 2026-12-31T23:59:59.000Z', 'max-uses none', 'reason "Run the nightly digest."', '',
    ].join('\n'));
  });

  it.each(fixture.cases.map((c) => [c.name, c] as const))('%s: builder bytes equal the fixture bytes', (_, c) => {
    const terms = grantTermsBytes(termsOf(c.terms));
    expect(terms.toString('utf8')).toBe(c.termsUtf8);
    expect(grantTermsHash(termsOf(c.terms))).toBe(c.termsHash);
    expect(sha256hex(c.termsUtf8)).toBe(c.termsHash);
    const payload = grantSignaturePayloadBytes(GRANT_SIGNATURE_PAYLOAD_V1, payloadOf(c));
    // Independent of the builder: the spec's five lines, LF after each, no CR.
    const literal = `hadron-grant-signature-v1\ngrant ${c.grantId}\nversion ${c.recordVersion}\nterms-hash ${c.termsHash}\nrequest ${c.requestId}\n`;
    expect(payload.toString('utf8')).toBe(literal);
    expect(payload.toString('utf8')).toBe(c.payloadUtf8);
    expect(payload.toString('base64')).toBe(c.canonical);
    expect(payload.includes(0x0d)).toBe(false);
    expect(signatureChallenge(payload).toString('hex')).toBe(c.challengeHex);
    expect(signatureChallenge(payload).toString('base64url')).toBe(c.challengeBase64url);
  });

  it('new grant requests pin v1, and a version the server cannot build is refused, never substituted', () => {
    expect(CURRENT_GRANT_SIGNATURE_PAYLOAD_VERSION).toBe('hadron-grant-signature-v1');
    const c = byName('spec-example');
    for (const v of ['hadron-grant-signature-v2', 'hadron-grant-signature-v0', SIGNATURE_PAYLOAD_V3, '']) {
      expect(() => grantSignaturePayloadBytes(v, payloadOf(c))).toThrow(UnsupportedSignaturePayloadError);
    }
  });

  it.each([
    ['uppercase terms hash', { termsHash: '0EF8421DCDD63E2052BEE076B041298658D05B293056AFC33DEEE231D92D1C4F' }],
    ['short terms hash', { termsHash: '0ef8421d' }],
    ['terms hash with a line break', { termsHash: '0ef8421dcdd63e2052bee076b041298658d05b293056afc33deee231d92d1c4\n' }],
    ['version 0', { recordVersion: 0 }],
    ['negative version', { recordVersion: -1 }],
    ['fractional version', { recordVersion: 1.5 }],
    ['unsafe version', { recordVersion: 2 ** 53 }],
    ['grant id with a space', { grantId: 'cm3k9x2b0000 2ab12cd34ef57' }],
    ['grant id with LF (a forged second line)', { grantId: 'cm3k9x2b00002ab12cd34ef57\nversion 9' }],
    ['grant id with CR', { grantId: 'cm3k9x2b00002ab12cd34ef57\r' }],
    ['empty grant id', { grantId: '' }],
    ['request id of 21 characters', { requestId: 'Q2hhbGxlbmdlUmVxdWVzd' }],
    ['request id with padding', { requestId: 'Q2hhbGxlbmdlUmVxdWVzdA==' }],
    ['request id with a standard-base64 character', { requestId: 'Q2hhbGxlbmdlUmVxdWVzd+' }],
  ])('refuses %s in the payload', (_, patch) => {
    expect(() => grantSignaturePayloadBytes(GRANT_SIGNATURE_PAYLOAD_V1, { ...payloadOf(byName('spec-example')), ...patch })).toThrow();
  });
});

describe('G2: the terms hash binds every term, and only as stored', () => {
  it('is stable under the key order the values object was built in', () => {
    const a = grantTermsHash({ ...SPEC, values: { b: 'x', a: 'y' } });
    const b = grantTermsHash({ ...SPEC, values: { a: 'y', b: 'x' } });
    expect(a).toBe(b);
    expect(grantTermsBytes({ ...SPEC, values: { b: 'x', a: 'y' } }).toString()).toContain('values {"a":"y","b":"x"}\n');
  });

  it.each([
    ['the App', { appId: 'cm3k9x2a00001ab12cd34ef5x' }],
    ['the holder kind', { holder: { kind: 'worker', id: '01a05c157fe171208eef57f6ddb9b701' } }],
    ['the holder id', { holder: { kind: 'agent', id: '01a05c157fe171208eef57f6ddb9b702' } }],
    ['the action', { action: 'schedule.update' }],
    ['a value', { values: { entryNode: '01a10408afb6716c80d6944e8845467c' } }],
    ['a value key', { values: { entrynode: '01a10408afb6716c80d6944e8845467b' } }],
    ['an added value', { values: { entryNode: '01a10408afb6716c80d6944e8845467b', other: 'x' } }],
    ['a value as a one-element list', { values: { entryNode: ['01a10408afb6716c80d6944e8845467b'] } }],
    ['the wildcard', { values: { entryNode: '*' } }],
    ['the start', { startsAt: new Date('2026-11-10T00:00:00.000Z') }],
    ['the expiry by one millisecond', { expiresAt: new Date('2026-12-31T23:59:59.001Z') }],
    ['no expiry', { expiresAt: null }],
    ['the count', { maxUses: 1 }],
    ['the reason', { reason: 'Run the nightly digest' }],
    ['the reason by a trailing space', { reason: 'Run the nightly digest. ' }],
  ])('changes with %s', (_, patch) => {
    expect(grantTermsHash({ ...SPEC, ...(patch as Partial<GrantTerms>) })).not.toBe(grantTermsHash(SPEC));
  });

  it('a value that reads like a line of the document stays inside its JSON string', () => {
    const bytes = grantTermsBytes({ ...SPEC, values: { entryNode: 'x"}\nreason "forged' } }).toString();
    expect(bytes.split('\n')).toHaveLength(10);
    expect(bytes).toContain('values {"entryNode":"x\\"}\\nreason \\"forged"}\n');
  });

  it('reads the holder from exactly one of the row\'s four holder columns', () => {
    const row: GrantTermsRow = {
      appId: SPEC.appId, userId: null, agentId: SPEC.holder.id, workerId: null, granteeAppId: null, action: SPEC.action,
      values: SPEC.values, startsAt: SPEC.startsAt, expiresAt: SPEC.expiresAt, maxUses: SPEC.maxUses, reason: SPEC.reason,
    };
    expect(grantTermsHash(grantTermsFromRow(row))).toBe(byName('spec-example').termsHash);
    expect(grantTermsFromRow({ ...row, agentId: null, userId: 'u1' }).holder).toEqual({ kind: 'user', id: 'u1' });
    expect(grantTermsFromRow({ ...row, agentId: null, workerId: 'w1' }).holder).toEqual({ kind: 'worker', id: 'w1' });
    expect(grantTermsFromRow({ ...row, agentId: null, granteeAppId: 'a1' }).holder).toEqual({ kind: 'app', id: 'a1' });
    expect(() => grantTermsFromRow({ ...row, agentId: null })).toThrow(GrantTermsError);
    expect(() => grantTermsFromRow({ ...row, userId: 'u1' })).toThrow(GrantTermsError);
  });

  const refused: Array<[string, Partial<GrantTerms> | Record<string, unknown>, string]> = [
    ['an App id with a space', { appId: 'cm3k9x2a 00001' }, 'BAD_TOKEN'],
    ['an App id with a tab', { appId: 'cm3k9x2a\t00001' }, 'BAD_TOKEN'],
    ['an empty App id', { appId: '' }, 'BAD_TOKEN'],
    ['a holder id with LF', { holder: { kind: 'agent', id: 'a\nb' } }, 'BAD_TOKEN'],
    ['a holder id with U+2028', { holder: { kind: 'agent', id: 'a\u2028b' } }, 'BAD_TOKEN'],
    ['a holder id with U+00A0', { holder: { kind: 'agent', id: 'a\u00a0b' } }, 'BAD_TOKEN'],
    ['a holder id with U+200B', { holder: { kind: 'agent', id: 'a\u200bb' } }, 'BAD_TOKEN'],
    ['a holder id with U+007F', { holder: { kind: 'agent', id: 'a\u007fb' } }, 'BAD_TOKEN'],
    ['a holder id with a lone surrogate', { holder: { kind: 'agent', id: 'a\ud800' } }, 'BAD_TOKEN'],
    ['an unknown holder kind', { holder: { kind: 'org', id: 'o1' } }, 'BAD_HOLDER'],
    ['an action with a space', { action: 'schedule create' }, 'BAD_TOKEN'],
    ['values that are a list', { values: ['x'] }, 'BAD_VALUES'],
    ['values that are null', { values: null }, 'BAD_VALUES'],
    ['values that are a string', { values: '{"entryNode":"x"}' }, 'BAD_VALUES'],
    ['a number value', { values: { entryNode: 1 } }, 'BAD_VALUES'],
    ['a boolean value', { values: { entryNode: true } }, 'BAD_VALUES'],
    ['a null value', { values: { entryNode: null } }, 'BAD_VALUES'],
    ['an empty-string value', { values: { entryNode: '' } }, 'BAD_VALUES'],
    ['a nested object value', { values: { entryNode: { id: 'x' } } }, 'BAD_VALUES'],
    ['an empty list', { values: { entryNode: [] } }, 'BAD_VALUES'],
    ['a list with a duplicate', { values: { entryNode: ['a', 'a'] } }, 'BAD_VALUES'],
    ['a list holding the wildcard', { values: { entryNode: ['a', '*'] } }, 'BAD_VALUES'],
    ['a list holding a number', { values: { entryNode: ['a', 1] } }, 'BAD_VALUES'],
    ['a value with a lone surrogate', { values: { entryNode: 'x\udc00' } }, 'BAD_VALUES'],
    ['an empty key', { values: { '': 'x' } }, 'BAD_VALUES'],
    ['a key with a lone surrogate', { values: { ['k\ud800']: 'x' } }, 'BAD_VALUES'],
    ['an invalid start', { startsAt: new Date(Number.NaN) }, 'BAD_TIME'],
    ['an expiry past year 9999', { expiresAt: new Date('+010000-01-01T00:00:00.000Z') }, 'BAD_TIME'],
    ['an expiry before year 0', { expiresAt: new Date('-000001-01-01T00:00:00.000Z') }, 'BAD_TIME'],
    ['a count of 0', { maxUses: 0 }, 'BAD_COUNT'],
    ['a fractional count', { maxUses: 1.5 }, 'BAD_COUNT'],
    ['a negative count', { maxUses: -2 }, 'BAD_COUNT'],
    ['an empty reason', { reason: '' }, 'BAD_REASON'],
    ['a spaces-only reason', { reason: '   ' }, 'BAD_REASON'],
    ['a reason with a lone surrogate', { reason: 'why \ud800' }, 'BAD_REASON'],
  ];
  it.each(refused)('refuses %s (%s), naming no value', (_, patch, reason) => {
    let err: unknown;
    try { grantTermsBytes({ ...SPEC, ...(patch as Partial<GrantTerms>) }); } catch (e) { err = e; }
    expect(err).toBeInstanceOf(GrantTermsError);
    expect((err as GrantTermsError).reason).toBe(reason);
    expect((err as GrantTermsError).code).toBe('GRANT_TERMS_UNREPRESENTABLE');
    expect((err as Error).message).not.toMatch(/cm3k9x2a|forged|surrogate|\\u/);
  });

  it('keeps a reason the DB can store: a tab-only reason is not refused (btrim trims spaces only)', () => {
    expect(grantTermsBytes({ ...SPEC, reason: '\t' }).toString()).toContain('reason "\\t"\n');
  });

  it('writes the first line of the terms document and nothing after the reason line', () => {
    const lines = grantTermsBytes(SPEC).toString().split('\n');
    expect(lines[0]).toBe(GRANT_TERMS_V1);
    expect(lines).toHaveLength(10);
    expect(lines[9]).toBe('');
  });
});

describe('G3: a grant payload and a node payload never verify for each other', () => {
  it('the node v3 builder is untouched by the grant prefix, and the two challenges for the same ids differ', () => {
    const c = byName('spec-example');
    const node = signaturePayloadBytes(SIGNATURE_PAYLOAD_V3, { nodeId: c.grantId, approvalHash: c.termsHash, requestId: c.requestId });
    const grant = grantSignaturePayloadBytes(GRANT_SIGNATURE_PAYLOAD_V1, payloadOf(c));
    expect(node.toString().split('\n')[0]).toBe('hadron-signature-v3');
    expect(grant.toString().split('\n')[0]).toBe('hadron-grant-signature-v1');
    expect(signatureChallenge(node).equals(signatureChallenge(grant))).toBe(false);
  });

  it('the node v3 builder refuses the grant prefix, and the grant builder refuses the node prefix', () => {
    const c = byName('spec-example');
    expect(() => signaturePayloadBytes(GRANT_SIGNATURE_PAYLOAD_V1, { nodeId: c.grantId, approvalHash: c.termsHash, requestId: c.requestId }))
      .toThrow(UnsupportedSignaturePayloadError);
    expect(() => grantSignaturePayloadBytes(SIGNATURE_PAYLOAD_V3, payloadOf(c))).toThrow(UnsupportedSignaturePayloadError);
  });

  it('the v3 node fixture still builds byte for byte', () => {
    const v3 = JSON.parse(readFileSync(new URL('../signaturePayload.v3.fixture.draft.json', import.meta.url), 'utf8')) as {
      cases: Array<{ nodeId: string; approvalHash: string; requestId: string; payloadUtf8: string }>;
    };
    for (const c of v3.cases) {
      expect(signaturePayloadBytes(SIGNATURE_PAYLOAD_V3, c).toString('utf8')).toBe(c.payloadUtf8);
    }
  });
});
